const int k_goblinWallSmashGoal = 5;
const int k_shamanWallSmashGoal = 5;
const int k_boarRampageCount = 5;

const float k_scrollingTime = 3.0f;
const float k_scrollingTransition = 0.5f;

ChallengeType StringToChallengeType (const wchar_t* text)
{
	if (wcscmp(text, L"PerfectHealth") == 0) return CT_PerfectHealth;
	if (wcscmp(text, L"GoblinSmasher") == 0) return CT_GoblinWallSmash;
	if (wcscmp(text, L"ShamanSmasher") == 0) return CT_ShamanWallSmash;
	if (wcscmp(text, L"BoarRampage") == 0) return CT_BoarRampage;
	if (wcscmp(text, L"GriffinFireballMaster") == 0) return CT_GriffinFireballMaster;
	if (wcscmp(text, L"GriffinFireballSuperMaster") == 0) return CT_GriffinFireballSuperMaster;
	if (wcscmp(text, L"FlickMaster") == 0) return CT_FlickMaster;
	if (wcscmp(text, L"OneHitOneKill") == 0) return CT_OneHitOneKill;
	if (wcscmp(text, L"ManyEnemiesWithSpecial") == 0) return CT_ManyEnemiesWithSpecial;
	if (wcscmp(text, L"ThatWasClose") == 0) return CT_ThatWasClose;
	if (wcscmp(text, L"WallSmasher") == 0) return CT_WallSmasher;
	if (wcscmp(text, L"GroundSmasher") == 0) return CT_GroundSmasher;
	if (wcscmp(text, L"MenuGoblins") == 0) return CT_MenuGoblins;
	if (wcscmp(text, L"MenuTrolls") == 0) return CT_MenuTrolls;
	if (wcscmp(text, L"MenuShamans") == 0) return CT_MenuShamans;
	if (wcscmp(text, L"ShamanCombo") == 0) return CT_ShamanCombo;
	if (wcscmp(text, L"TrollCombo") == 0) return CT_TrollCombo;
	if (wcscmp(text, L"ComboMaster") == 0) return CT_ComboMaster;
	return CT_None;
}

const wchar_t* ChallengeTypeToString (ChallengeType type)
{
	switch (type)
	{
	case CT_PerfectHealth: return L"PerfectHealth";
	case CT_GoblinWallSmash: return L"GoblinSmasher";
	case CT_ShamanWallSmash: return L"ShamanSmasher";
	case CT_BoarRampage: return L"BoarRampage";
	case CT_GriffinFireballMaster: return L"GriffinFireballMaster";
	case CT_GriffinFireballSuperMaster: return L"GriffinFireballSuperMaster";
	case CT_FlickMaster: return L"FlickMaster";
	case CT_OneHitOneKill: return L"OneHitOneKill";
	case CT_ManyEnemiesWithSpecial: return L"ManyEnemiesWithSpecial";
	case CT_ThatWasClose: return L"ThatWasClose";
	case CT_WallSmasher: return L"WallSmasher";
	case CT_GroundSmasher: return L"GroundSmasher";
	case CT_MenuGoblins: return L"MenuGoblins";
	case CT_MenuTrolls: return L"MenuTrolls";
	case CT_MenuShamans: return L"MenuShamans";
	case CT_ShamanCombo: return L"ShamanCombo";
	case CT_TrollCombo: return L"TrollCombo";
	case CT_ComboMaster: return L"ComboMaster";
	default: return L"None";
	}
}

Challenge::Challenge ()
{
	setType(CT_None);
}

ChallengeType Challenge::getType ()
{
	return m_type;
}

void Challenge::setType (ChallengeType type)
{
	m_type = type;

	m_scrollingTitle = 0;
	m_scrollingTimer = 0.0f;

	m_challengeComplete = false;
	m_specialWeaponUsed = false;

	m_enemiesKilledBySpecial = 0;
	m_enemiesKilledOnWall = 0;
	m_enemiesKilledOnGround = 0;
	m_combos = 0;
	m_enemiesEaten = 0;

	m_wallSmashKind = UK_Unknown;
	m_wallSmashCount = 0;
	if (type == CT_GoblinWallSmash)
	{
		m_wallSmashKind = UK_Goblin;
		m_wallSmashGoal = k_goblinWallSmashGoal;
	}
	if (type == CT_ShamanWallSmash)
	{
		m_wallSmashKind = UK_Shaman;
		m_wallSmashGoal = k_shamanWallSmashGoal;
	}
}

void Challenge::update (float time)
{
	if (m_scrollingTitle)
	{
		m_scrollingTimer += time;
		if (m_scrollingTimer > k_scrollingTime)
		{
			m_scrollingTitle = 0;
		}
	}
}

void Challenge::draw ()
{
	if (m_scrollingTitle)
	{
		//float alpha = LinearUpFlatDown(m_scrollingTimer, 0, k_scrollingTransition, k_scrollingTime - k_scrollingTransition, k_scrollingTime);
		float x = LinearUpFlatDown(m_scrollingTimer, 0, k_scrollingTransition, k_scrollingTime - k_scrollingTransition, k_scrollingTime);

		ASprite* spr = CPlayfield::GetInstance()->getSpriteIngame();
		// TODO: Fix
		spr->PaintFrame(MENU_F_MENU_CHALLENGE_BG, 170 * x - 170, 30);

		r2i rect = spr->GetFrameRect( MENU_F_MENU_CHALLENGE_BG );

		stringw str = FormatString(L"%s\n%s", m_failed ? _TXT(CHALLENGES_FAILED) : _TXT(CHALLENGES_COMPLETED), m_scrollingTitle);

		const char* challengeFont = m_failed ? "ChallengeFailed" : "Challenge";
		float scaleFont = 0.85;
		float lastFontScaleX = __FONT(challengeFont)->GetScaleX();
		float lastFontScaleY = __FONT(challengeFont)->GetScaleY();
		__FONT( challengeFont )->SetScale( lastFontScaleX*scaleFont, lastFontScaleY*scaleFont );

		__FONT( challengeFont )->DrawWrappedText(str.c_str(), 170 * x - 170 + 82, 30 + 33, rect.getWidth() - 5, CFont::HVCENTER, 255);

		__FONT( challengeFont )->SetScale( lastFontScaleX, lastFontScaleY );
	
	}
}

void Challenge::gateDamaged ()
{
	if (m_type == CT_PerfectHealth)
		failChallenge();
}

void Challenge::unitDied (int damageSource, UnitKind kind)
{
	switch (m_type)
	{
		case CT_GoblinWallSmash:
		case CT_ShamanWallSmash:
		{
			if (kind == m_wallSmashKind && m_wallSmashCount < m_wallSmashGoal && damageSource == UDS_WallHit)
			{
				++m_wallSmashCount;
				if (m_wallSmashCount == m_wallSmashGoal)
				{
					completeChallenge();
				}
			}
			break;
		}

		case CT_WallSmasher:
		{
			if (damageSource == UDS_WallHit)
			{
				++m_enemiesKilledOnWall;
				if (m_enemiesKilledOnWall >= 15)
					completeChallenge();
			}
			break;
		}

		case CT_GroundSmasher:
		{
			if (damageSource == UDS_GroundDrag)
			{
				++m_enemiesKilledOnGround;
				if (m_enemiesKilledOnGround >= 15)
					completeChallenge();
			}
			break;
		}
	}
}

void Challenge::levelEnded (bool maxHealth, bool criticalHealth, bool win)
{
	if (win)
	{
		if (m_type == CT_PerfectHealth && maxHealth)
			completeChallenge();
		if (m_type == CT_FlickMaster && !m_specialWeaponUsed)
			completeChallenge();
		if (m_type == CT_ThatWasClose && criticalHealth)
			completeChallenge();
	}

	if (!m_challengeComplete && m_type != CT_None)
		failChallenge();
}

void Challenge::unitWasHitByBoar (int* unitsByKind)
{
	if (m_type == CT_BoarRampage && !m_challengeComplete &&
		unitsByKind[UK_Goblin] + unitsByKind[UK_BoarRider] >= k_boarRampageCount)
	{
		completeChallenge();
	}
}

void Challenge::unitsWereKilledByWeapon (int damageSource, int* unitsHitByKind)
{
	if (m_challengeComplete) return;

	int differentTypes = 0;
	int totalKilled = 0;
	for (int i = 0; i < UK_Unknown; ++i)
	{
		if (unitsHitByKind[i] > 0) ++differentTypes;
		totalKilled += unitsHitByKind[i];
	}

	m_enemiesKilledBySpecial += totalKilled;

	if (m_type == CT_GriffinFireballMaster && differentTypes >= 3 && (damageSource == UDS_Fireball || damageSource == UDS_GriffinSmash))
		completeChallenge();
	if (m_type == CT_GriffinFireballSuperMaster && totalKilled >= 5 && (damageSource == UDS_Fireball || damageSource == UDS_GriffinSmash))
		completeChallenge();
	if (m_type == CT_ManyEnemiesWithSpecial && m_enemiesKilledBySpecial >= 30)
		completeChallenge();
}

void Challenge::specialWeaponUsed ()
{
	m_specialWeaponUsed = true;
	if (m_type == CT_FlickMaster)
		failChallenge();
}

void Challenge::hydraHasEatenUnit (UnitKind kind)
{
	if (m_type == CT_MenuGoblins && kind == UK_Goblin ||
		m_type == CT_MenuShamans && kind == UK_Shaman ||
		m_type == CT_MenuTrolls  && kind == UK_Troll)
	{
		++m_enemiesEaten;
		if (m_enemiesEaten >= 5)
			completeChallenge();
	}
	int unitsHitByKind[UK_Unknown + 1] = { 0 };
	unitsHitByKind[kind] = 1;
	unitsWereKilledByWeapon(UDS_Petrify, unitsHitByKind);
}

void Challenge::comboAchieved (UnitKind kind)
{
	if (m_type == CT_ShamanCombo && kind == UK_Shaman ||
		m_type == CT_TrollCombo  && kind == UK_Troll)
		completeChallenge();

	if (m_type == CT_ComboMaster && ++m_combos >= 5)
		completeChallenge();

	//__MGR_SOUNDS()->play( SFX_CHALLENGE_COMPLETED );
}

void Challenge::completeChallenge ()
{
	if (!m_challengeComplete)
	{
		m_failed = false;
		m_scrollingTitle = _TXT(CHALLENGES_TITLE_0 + m_type);
		m_scrollingTimer = 0.0f;
		m_challengeComplete = true;
		int reward = 100;
		IAttributes* attr = __GAME_CONFIG()->getAttributes(L"challenge", ChallengeTypeToString(m_type));
		if (attr && attr->existsAttribute("Reward"))
			reward = attr->getAttributeAsInt("Reward");
		CPlayfield::GetInstance()->addMoney(0, reward, v2f(240, 90), _TXT(INGAME_BONUS), 3.0f);

		__ACHIEVEMENTS()->setValue("Challenger", (1 << (s32)m_type));
	}
}

void Challenge::failChallenge ()
{
	if (!m_challengeComplete)
	{
		m_failed = true;
		m_scrollingTitle = _TXT(CHALLENGES_TITLE_0 + m_type);
		m_scrollingTimer = 0.0f;
		m_challengeComplete = true;
	}
}

const TChar* Challenge::getDescription ()
{
	return _TXT(CHALLENGES_DESCRIPTION_0 + m_type);
}
